  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 21, $j$6.1 Entrepreneurship and Starting a Small Business$j$, $j${"readings": [{"title": "Proverbs 31 (King James Version)", "url": "/portal/bible/Proverbs/31"}], "body": "An entrepreneur is a person who starts and runs a business and accepts its risk in hope of profit. Proverbs 31:16 describes a woman of enterprise: She considereth a field, and buyeth it: with the fruit of her hands she planteth a vineyard. Colossians 3:23 says, And whatsoever ye do, do it heartily, as to the Lord, and not unto men. Honest enterprise serves customers and provides for families.\n\nA business begins with a need and an idea. Ask who your customers are, what problem you solve and why they would choose you. Test the idea on a small scale before spending much. A business plan puts the idea on paper: the product or service, the market, competition, pricing, startup costs, how it will be run and how it will make money. Luke 14:28 applies again, count the cost before you build.\n\nLearn the basic money words. Revenue is the money coming in from sales. Expenses are the costs of running the business. Profit equals revenue minus expenses. Fixed costs, such as rent, stay the same, and variable costs, such as materials, change with sales. The break even point is where revenue equals expenses. Price must cover costs and leave a profit. Cash flow is the timing of money in and out, and many businesses fail when they run out of cash.\n\nChoose a legal structure. A sole proprietorship is owned by one person with no separation between owner and business. A limited liability company, or LLC, can separate personal and business liability. A corporation is a separate legal entity. A nonprofit organization serves a public purpose and has special rules. In Florida, businesses register with the Division of Corporations at Sunbiz, and may need local licenses and a federal Employer Identification Number. Get advice from an attorney or accountant.\n\nKeep business and personal money separate. Keep records, pay taxes, including self employment tax, and treat workers and customers fairly. Proverbs 11:1 says, A false balance is abomination to the LORD: but a just weight is his delight. Young entrepreneurs should have a parent or mentor involved and follow laws about minors in business.\n\nYour task: (1) Define revenue, expense, profit and break even. (2) Name four parts of a business plan. (3) Compare a sole proprietorship and an LLC.\n\nFlorida standards: SS.912.FL.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.FL", "script": "Welcome back. Listen, Proverbs 31:16 says, She considereth a field, and buyeth it: with the fruit of her hands she planteth a vineyard. Honest enterprise serves customers and provides for families.\n\nNow watch this. Start with a need. Who are your customers, what problem do you solve and why would they choose you? Test your idea small. A business plan covers the product, market, competition, pricing, startup costs and how it makes money. Count the cost, as in Luke 14:28.\n\nRevenue is money from sales. Expenses are costs. Profit is revenue minus expenses. Fixed costs stay the same. Variable costs change with sales. Break even is where revenue equals expenses. Price must cover costs and leave a profit. Watch cash flow, because many businesses fail when cash runs out.\n\nA sole proprietorship has no separation between owner and business. An LLC can separate personal and business liability. In Florida, businesses register with Sunbiz and may need local licenses and an Employer Identification Number. Get advice from an attorney or accountant.\n\nKeep business and personal money separate, keep records and pay taxes. Proverbs 11:1 says, a just weight is his delight.\n\nYour task is to define business terms, name plan parts and compare structures. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.1 Entrepreneurship and Starting a Small Business$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 22, $j$6.2 Consumer Rights, Contracts and Honest Dealing$j$, $j${"readings": [{"title": "Proverbs 20 (King James Version)", "url": "/portal/bible/Proverbs/20"}], "body": "Every consumer should know their rights and responsibilities. Proverbs 20:23 says, Divers weights are an abomination unto the LORD; and a false balance is not good. God cares about honesty in buying and selling, so believers must be honest consumers as well as honest sellers.\n\nA contract is a legally binding agreement. Common contracts include phone plans, leases, gym memberships, car loans and employment agreements. Before signing, read the entire contract, including the fine print, ask questions about anything unclear, get promises in writing and keep a copy. Look for the total cost, fees, length of the commitment, automatic renewals, cancellation terms and penalties. Do not sign under pressure. In general, contracts signed by minors can be cancelled by the minor in many situations, but the law is complex, and parents or guardians usually sign or cosign. Never assume you can walk away.\n\nConsumers have important protections. Laws prohibit deceptive advertising and unfair practices. The Federal Trade Commission, or FTC, enforces consumer protection laws, and the Consumer Financial Protection Bureau, or CFPB, supervises many financial products. In Florida, consumer complaints can be filed with the Florida Department of Agriculture and Consumer Services and the Florida Attorney General. Before filing, try to resolve the problem directly. Keep receipts, emails and notes of calls, write a clear letter stating the problem and the remedy you want, and follow up. The Better Business Bureau also collects complaints.\n\nConsumers have responsibilities too: pay what is owed, return items honestly, respect the terms of a sale and avoid false claims or fake reviews. Do not shoplift, steal digital goods or copy copyrighted material without permission. Proverbs 22:1 teaches that a good name is better than great riches.\n\nBe a careful buyer online. Check that a website is real, look for secure payment, read reviews from reliable sources and use a credit card or trusted payment method that offers dispute protection. Read privacy policies, since your data has value.\n\nYour task: (1) List five things to check before signing a contract. (2) Name two agencies that help consumers. (3) Explain how Proverbs 20:23 applies to buyers and sellers.\n\nFlorida standards: SS.912.FL.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.FL", "script": "Welcome back. Listen, Proverbs 20:23 says, Divers weights are an abomination unto the LORD; and a false balance is not good. God cares about honesty in buying and selling.\n\nNow watch this. A contract is a legally binding agreement, like a phone plan, a lease, a gym membership or a car loan. Read the whole contract, including the fine print. Ask questions. Get promises in writing. Keep a copy. Look at total cost, fees, length, automatic renewals and cancellation terms. Do not sign under pressure. Minors can often cancel contracts, but the law is complex and parents usually sign.\n\nConsumers are protected. The FTC enforces consumer protection laws. The CFPB supervises many financial products. In Florida you can file with the Department of Agriculture and Consumer Services and the Attorney General. First try to resolve the problem directly. Keep receipts, emails and notes of calls.\n\nConsumers have responsibilities too. Pay what you owe, return items honestly and avoid fake reviews. Respect copyright.\n\nShop online carefully. Check that the site is real, use secure payment and a method with dispute protection.\n\nYour task is to list contract checks, name agencies and explain Proverbs 20:23. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.2 Consumer Rights, Contracts and Honest Dealing$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 23, $j$6.3 Contentment, Wealth and Legacy$j$, $j${"readings": [{"title": "Matthew 6 (King James Version)", "url": "/portal/bible/Matthew/6"}], "body": "Financial skill is a means and not an end. Jesus said in Matthew 6:19 to 21, Lay not up for yourselves treasures upon earth, where moth and rust doth corrupt, and where thieves break through and steal: But lay up for yourselves treasures in heaven. And in verse 21: For where your treasure is, there will your heart be also. How we handle money shows where our hearts are.\n\nScripture does not condemn wealth, but it warns of its danger. Ecclesiastes 5:10 says, He that loveth silver shall not be satisfied with silver; nor he that loveth abundance with increase: this is also vanity. Matthew 6:33 gives the priority: But seek ye first the kingdom of God, and his righteousness; and all these things shall be added unto you. Philippians 4:19 gives the promise: But my God shall supply all your need according to his riches in glory by Christ Jesus. The believer works hard, plans well and trusts God for the outcome.\n\nContentment is not laziness, but gratitude with a right sense of enough. A person who always wants more is never satisfied. Practice contentment by thanking God regularly, comparing your needs with your wants, limiting social media comparison and enjoying simple blessings. Contentment also supports generosity, because a content person can give freely.\n\nLegacy is what we leave behind. Financial legacy includes savings, property and the habits and values we teach. Proverbs 13:22 speaks of an inheritance for children's children. Yet the best inheritance includes faith, character and wisdom. Teach younger family members to work, save, give and avoid debt. Plan how the church, ministries and charities you love might be supported through your giving and your will. Talk openly with family so there is no confusion.\n\nGenerosity beyond the tithe is a mark of maturity. Give of your time and skills, mentor others, support missions and care for widows, orphans and neighbors in need. Budget for generosity, and look for ways to serve your community. A life of stewardship brings joy that money alone cannot.\n\nYour task: (1) Explain Matthew 6:21 in your own words. (2) Describe three ways to practice contentment. (3) Write a short statement of the legacy you hope to leave.\n\nFlorida standards: SS.912.FL.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.FL", "script": "Welcome back. Listen, Matthew 6:21 says, For where your treasure is, there will your heart be also. How we handle money shows where our hearts are.\n\nNow watch this. Scripture does not condemn wealth, but it warns of its danger. Ecclesiastes 5:10 says, He that loveth silver shall not be satisfied with silver. Matthew 6:33 sets the priority: But seek ye first the kingdom of God, and his righteousness; and all these things shall be added unto you. Philippians 4:19 says, my God shall supply all your need according to his riches in glory by Christ Jesus. We work hard, plan well and trust God.\n\nContentment is gratitude with a right sense of enough. Thank God regularly, compare needs with wants, limit social media comparison and enjoy simple blessings. A content person can give freely.\n\nLegacy is what we leave behind: savings, property, habits and values. The best inheritance includes faith, character and wisdom. Teach younger family members to work, save, give and avoid debt. Plan how your giving and your will can support the church and ministries. Talk openly with family.\n\nGenerosity goes beyond the tithe. Give time and skills. Mentor others. Care for the needy.\n\nYour task is to explain Matthew 6:21, describe contentment and write a legacy statement. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.3 Contentment, Wealth and Legacy$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 24, $j$6.4 Your Personal Financial Plan$j$, $j${"readings": [{"title": "Proverbs 16 (King James Version)", "url": "/portal/bible/Proverbs/16"}], "body": "A plan ties together everything we have studied. Proverbs 16:3 says, Commit thy works unto the LORD, and thy thoughts shall be established. Proverbs 16:9 says, A man's heart deviseth his way: but the LORD directeth his steps. We plan with diligence and hold our plans with humility before God.\n\nA personal financial plan has several parts. First, set goals. Write short, medium and long term SMART goals for your life. Second, make a budget that includes giving, saving and spending. Third, build an emergency fund, starting with a small starter fund and growing it. Fourth, manage debt: avoid it where possible, pay on time and eliminate high interest balances first. Fifth, protect your credit and your identity. Sixth, protect against risk with insurance and sound records. Seventh, invest for the long term using diversified, low cost options, and use retirement accounts and employer matches. Eighth, plan your giving and legacy. Ninth, keep learning and seek counsel.\n\nPlans must change with life events. Graduating, getting a first job, moving out, marrying, having children, buying a home, changing careers, caring for parents, facing illness or retiring all require updates. Review your plan at least once a year and after any big change.\n\nBuild a support team. Parents, mentors, pastors and trusted professionals provide counsel. Proverbs 15:22 says, Without counsel purposes are disappointed: but in the multitude of counsellors they are established. Choose advisers who are licensed, transparent about fees and legally bound to act in your interest. Be cautious about anyone who pressures you or promises easy riches.\n\nHabits drive results. Spend less than you earn, give first, save automatically, avoid unneeded debt, live below your means and keep learning. Small steady actions over decades create large results. Colossians 3:23 reminds us to do it heartily, as to the Lord.\n\nFor your final assessment, you will put together a complete personal financial plan.\n\nYour task: (1) List the nine parts of a personal financial plan. (2) Name three life events that change a plan. (3) Describe who is on your support team.\n\nFlorida standards: SS.912.FL.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.FL", "script": "Welcome back. Listen, Proverbs 16:3 says, Commit thy works unto the LORD, and thy thoughts shall be established. And Proverbs 16:9 says, A man's heart deviseth his way: but the LORD directeth his steps. We plan with diligence and hold our plans with humility.\n\nNow watch this. A plan has parts. Set goals. Make a budget with giving, saving and spending. Build an emergency fund. Manage debt. Protect your credit and identity. Protect against risk with insurance and records. Invest for the long term in diversified, low cost options. Plan your giving and legacy. Keep learning and seek counsel.\n\nLife changes the plan. Graduating, a first job, moving out, marriage, children, a home, a new career, caring for parents, illness or retirement all call for updates. Review at least once a year.\n\nBuild a support team of parents, mentors, pastors and trusted professionals. Proverbs 15:22 says, Without counsel purposes are disappointed. Choose advisers who are licensed, clear about fees and bound to act in your interest. Be cautious of pressure and promises of easy riches.\n\nHabits drive results. Spend less than you earn, give first, save automatically, avoid unneeded debt and keep learning.\n\nYour task is to list the parts of a plan, name life events and describe your support team. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.4 Your Personal Financial Plan$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 6, $j$Assessment 6: Enterprise, Consumer Rights, Legacy and Your Plan$j$, $j${"prompt": "Write a report of at least 250 words on enterprise, consumer rights, legacy and planning. Use complete sentences and label each part. Proverbs 16:3 says, Commit thy works unto the LORD, and thy thoughts shall be established.\n\nPart 1: Define revenue, expense, profit and break even. Describe a small business idea for a young person, with its customers, startup costs and prices, and calculate the profit if revenue is 800 dollars and expenses are 550 dollars.\nPart 2: List five things to check before signing a contract. Name two agencies that help consumers and describe how to file a complaint.\nPart 3: Explain Matthew 6:21, Matthew 6:33 and Ecclesiastes 5:10. Describe three ways to practice contentment.\nPart 4: Write a legacy statement of at least four sentences describing the faith, character and financial habits you hope to leave.\nPart 5: List the nine parts of a personal financial plan, and name three life events that would require you to update it.", "rubric": "100 points. Part 1: 25 points. Part 2: 20 points. Part 3: 20 points. Part 4: 15 points. Part 5: 15 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 6: Enterprise, Consumer Rights, Legacy and Your Plan$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 6, $j$Discussion 6: Where Your Treasure Is$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes a person who showed generosity, contentment or honest business dealings, with no names unless the person agrees, (2) explains in your own words how a Christian can work hard and plan well while trusting God, (3) explains what legacy you would like to leave, and (4) connects your answer to Matthew 6:21, Matthew 6:33, Proverbs 16:3 or Philippians 4:19. Then write a respectful reply of at least 40 words to another student's post, or answer this question: How can contentment and ambition live together? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 6: Where Your Treasure Is$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 26, $j$Check 6.1: Entrepreneurship and Starting a Small Business$j$, $j${"questions": [{"q": "Profit is calculated as:", "options": ["Price times two", "Revenue minus expenses", "Expenses minus taxes", "Revenue plus expenses"]}, {"q": "The point where revenue equals expenses is the:", "options": ["Deductible", "Break even point", "Maturity date", "Premium"]}, {"q": "A written document describing a business idea, market and costs is a:", "options": ["W2", "Business plan", "Pay stub", "Budget deficit"]}, {"q": "Keeping business and personal money separate is:", "options": ["A wise practice", "Unnecessary", "Illegal", "Only for large firms"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.1: Entrepreneurship and Starting a Small Business$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,1,1,0}'::int[], array[$j$Profit is what remains after expenses.$j$,$j$Break even means neither profit nor loss.$j$,$j$A business plan puts the idea on paper.$j$,$j$Separation helps records and liability.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.1: Entrepreneurship and Starting a Small Business$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 27, $j$Check 6.2: Consumer Rights, Contracts and Honest Dealing$j$, $j${"questions": [{"q": "A legally binding agreement is a:", "options": ["Coupon", "Receipt only", "Contract", "Statement of faith"]}, {"q": "Before signing a contract you should:", "options": ["Ignore cancellation terms", "Sign quickly", "Read all of it, including the fine print", "Skip the fees"]}, {"q": "A federal agency that enforces consumer protection laws is the:", "options": ["FDA only", "NFL", "FTC", "NASA"]}, {"q": "Proverbs 20:23 says divers weights are:", "options": ["A measure of wealth", "An abomination unto the LORD", "A reward", "Required"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.2: Consumer Rights, Contracts and Honest Dealing$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,2,2,1}'::int[], array[$j$A contract creates legal obligations.$j$,$j$Understand the terms first.$j$,$j$The Federal Trade Commission protects consumers.$j$,$j$God hates dishonest measures.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.2: Consumer Rights, Contracts and Honest Dealing$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 28, $j$Check 6.3: Contentment, Wealth and Legacy$j$, $j${"questions": [{"q": "Matthew 6:21 says where your treasure is, there will your:", "options": ["Heart be also", "Home be built", "Tax be due", "Debt grow"]}, {"q": "Ecclesiastes 5:10 says he that loveth silver shall:", "options": ["Become wise automatically", "Not be satisfied with silver", "Always be content", "Pay no tax"]}, {"q": "The priority in Matthew 6:33 is to seek first:", "options": ["The kingdom of God", "Fame", "A new car", "A large bank account"]}, {"q": "The best inheritance a family can pass on includes:", "options": ["Nothing", "Only property", "Faith, character and wisdom as well as resources", "Only debt"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.3: Contentment, Wealth and Legacy$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,0,2}'::int[], array[$j$Our treasure shows where our heart is.$j$,$j$The love of money never satisfies.$j$,$j$Put God first.$j$,$j$Values matter most.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.3: Contentment, Wealth and Legacy$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 29, $j$Check 6.4: Your Personal Financial Plan$j$, $j${"questions": [{"q": "A personal financial plan should be reviewed:", "options": ["At least once a year and after big life changes", "Never", "Only at retirement", "Only when rich"]}, {"q": "Which belongs in a complete financial plan?", "options": ["Only entertainment", "Only taxes", "Only investing", "Giving, saving, insurance and debt management"]}, {"q": "Proverbs 15:22 teaches that purposes are established by:", "options": ["Secrecy", "A multitude of counsellors", "Haste", "Luck"]}, {"q": "A wise financial adviser is:", "options": ["Unwilling to answer questions", "Promising guaranteed riches", "Licensed and clear about fees", "Pressuring and secretive"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.4: Your Personal Financial Plan$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,3,1,2}'::int[], array[$j$Plans must change with life.$j$,$j$A plan covers all areas.$j$,$j$Seek counsel.$j$,$j$Transparency and duty to you matter.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.4: Your Personal Financial Plan$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 30, $j$Unit Quiz 6: Enterprise, Consumer Rights, Legacy and Your Plan$j$, $j${"questions": [{"q": "Revenue minus expenses equals:", "options": ["Penalty", "Premium", "Principal", "Profit"]}, {"q": "Which legal form can separate personal and business liability?", "options": ["Pay stub", "Receipt", "LLC", "Coupon"]}, {"q": "Before signing a contract you should:", "options": ["Ignore fees", "Rely on a verbal promise only", "Read the whole thing and keep a copy", "Sign without reading"]}, {"q": "Which agency enforces consumer protection laws?", "options": ["FTC", "FAA only", "NASA", "NBA"]}, {"q": "Proverbs 20:23 teaches that false balances are:", "options": ["Required", "Rewarded", "Not good", "Smart"]}, {"q": "Matthew 6:33 tells us to seek first:", "options": ["Applause", "Debt", "Riches", "The kingdom of God"]}, {"q": "A financial legacy includes:", "options": ["Only cash", "Only a house", "Nothing", "Resources and the values we teach"]}, {"q": "Proverbs 16:9 says a man's heart deviseth his way, but:", "options": ["Luck rules his steps", "The LORD directeth his steps", "No one guides him", "Money rules his steps"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 6: Enterprise, Consumer Rights, Legacy and Your Plan$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,2,2,0,2,3,3,1}'::int[], array[$j$That is profit.$j$,$j$A limited liability company separates liability.$j$,$j$Understanding the terms protects you.$j$,$j$The FTC protects consumers.$j$,$j$Honest measures please God.$j$,$j$Put God first.$j$,$j$Faith and character are part of it.$j$,$j$God guides the plans we make.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 6: Enterprise, Consumer Rights, Legacy and Your Plan$j$ on conflict (item_id) do nothing;
